    fidelity: {
      "level": "behavioral",
      "areas": {
        "logic": {
          "level": "ok",
          "note": "Runs the real compiled firmware on an ATmega328P emulator (avr8js): GPIO, timers, USART, ADC, watchdog, interrupts, SPI and TWI (I2C, master mode) behave like the chip; Wire and SPI talk to the I2C and SPI parts wired to SDA/SCL (A4/A5) and MOSI/MISO/SCK (D11/D12/D13)."
        },
        "timing": {
          "level": "approx",
          "note": "Cycle-counted at 16 MHz on a deterministic virtual clock, so delay()/millis() are exact in virtual time. Peripherals the emulator lacks (e.g. some timer modes, sleep) and the crystal's ±50 ppm drift are not modelled."
        },
        "analog": {
          "level": "approx",
          "note": "Pins are ideal sources with 25 Ω output resistance. Digital inputs use the datasheet thresholds (low ≤ 0.3·VCC, high ≥ 0.6·VCC) and keep their last level in between. The ADC reads the solved net voltage against a 5 V reference; AREF, noise and input capacitance are ignored."
        },
        "power": {
          "level": "approx",
          "note": "5 V / 3.3 V rails are stiff sources. Per-pin current above 40 mA is flagged; total-package (200 mA) and regulator limits, VIN and brownout are not simulated."
        },
        "radio": {
          "level": "n/a",
          "note": "No radio on this board."
        }
      },
      "emulates": [
        "ATmega328P CPU at 16 MHz via avr8js",
        "Digital I/O with pull-ups",
        "USART0 serial on D0/D1",
        "On-board L LED on D13 and ON LED",
        "Per-pin over-current check (40 mA)"
      ],
      "doesNotEmulate": [
        "USB-serial chip (16U2) and auto-reset timing",
        "Bootloader (firmware is loaded directly)",
        "RESET pin and the reset button",
        "VIN, barrel jack and regulator limits",
        "Brownout detector",
        "Pin capacitance",
        "EEPROM persistence between runs",
        "Target (slave) mode of the two-wire interface, Wire.begin(address): the board can only be the bus master",
        "Two-wire bus electrical detail: the bus carries whole bytes, not SDA/SCL edges, so clock stretching, rise times and bus capacitance are not modelled",
        "Floating inputs: an input with nothing driving it reads LOW instead of random noise (the simulator warns about it)"
      ],
      "testOnRealDevice": [
        "Total current from many pins (200 mA package limit)",
        "Anything powered from VIN or the 3.3 V pin (50 mA max)",
        "Analog readings near the input thresholds",
        "Upload through the bootloader (arduino-cli upload)"
      ]
    },
